INSERT INTO boe_inject.unit_version_stage (id,unit_id,body,valid_from,evidence_instrument,evidence_url,evidence_quote) VALUES
('boe26-1b528c1be07db20e09789baf','cmpzcvdug0c9ivtrknfzrw9ri','تهدف الهيئة إلى تنظيم نشاط النقل العام والإشراف عليه وعلى سلامة تشغيل مرافقه وتجهيزاته وحسن إدارتها، وتوفيره بالمستوى الجيد والكلفة الملائمة، وتنظيم الاستثمار فيه بما يتفق مع أهداف التنمية الاقتصادية والاجتماعية في المملكة، وتراعى في كل ذلك الجوانب الفنية والبيئية والتكامل مع أنظمة النقل الجوي. وللهيئة في سبيل تحقيق أهدافها ممارسة المهمات والاختصاصات الآتية:

1 - إعداد الخطط السنوية والخمسية لنشاطاتها في إطار الأهداف والسياسات العامة لها بالتنسيق مع الجهات ذات العلاقة.

2 - الإشراف على تنفيذ خطط النقل العام على مستوى المملكة، والتأكد من توافر التمويل لأنشطته من مصادره المختلفة.

3 - اقتراح السياسات العامة والتشريعات الخاصة بالنقل العام، والإشراف على تنفيذها بعد اعتمادها.

4 - ضمان عدالة المنافسة بين مقدمي خدمات النقل العام.

5 - إجراء البحوث والدراسات اللازمة لتقويم نشاط النقل العام، والعمل على تطويره باستمرار.

6 - تحديد شبكة خطوط النقل العام ومساراتها.

7 - وضع أسس تنظيم الأنشطة الخاصة بمرافق النقل العام وإداراتها.

8 - وضع المواصفات والشروط الفنية ومعايير السلامة اللازمة لوسائل ووسائط النقل العام، بالمشاركة والتنسيق مع الجهات ذات العلاقة.

9 - إصدار التراخيص والتصاريح لجميع وسائل النقل العام، وإلغاؤها في حال مخالفة أحكام الأنظمة ذات الصلة.

10 - تحديد مواقع مرافق النقل العام – بالتنسيق مع الجهات ذات العلاقة – والإشراف على خدماتها، بما في ذلك محطات الوصول والانطلاق لوسائط النقل العام وأهمية قربها من المطارات.

11 - اقتراح آلية لتنظيم أجور النقل العام وأسس تسعيرها، ومتابعة الالتزام بها بعد اعتماد الأجور من الجهات المختصة.

12 - مراقبة وسائل النقل العام ومرافقه في المملكة، وإعادة هيكلتها بما يتناسب مع الحاجة إليها.

13 - توظيف التقنية في تنفيذ ومراقبة أعمال الهيئة ومهماتها.

14 - إعادة الدراسات اللازمة لمخططات النقل العام وتصميم منظوماته.

15 - مراقبة الالتزام بتنفيذ العقود المبرمة بين الهيئة والأطراف الأخرى.

16 - العمل على حماية مصالح المستخدمين المتعلقة بخدمات النقل العام، ومراقبة أداء المرخصين والمصرح لهم بتقديم تلك الخدمات، واتخاذ الإجراءات التي تكفل تقيدهم بشروط التراخيص والتصاريح الممنوحة لهم.

17 - التأكد من سلامة وسائط النقل العام بالتعاون والتنسيق مع الجهات ذات العلاقة.

18 - توفير الظروف الملائمة لجذب الاستثمارات في مجال النقل العام.

19 - العمل على وضع المواصفات اللازمة للحد من التلوث البيئي المرتبط بأنشطة النقل العام، بالتعاون مع الجهات المختصة.

20 - التنسيق مع الهيئة العامة للطيران المدني والجهات المعنية الأخرى لضمان تنفيذ الاستراتيجية الوطنية للنقل.

21 - تمثيل المملكة في المنظمات الدولية والإقليمية ذات العلاقة بالنقل العام.

22 - متابعة تنفيذ اتفاقيات النقل المبرمة بين المملكة والدول الأخرى.

23 - التحقيق فنياً في حوادث النقل العام التي تنتج منها خسائر في الأرواح أو الممتلكات أو تعطيل لأنشطة النقل العام، بالمشاركة مع الجهات المختصة.

24 - القيام بأي مهمة أخرى تكلف بها في مجال اختصاصها','2016-03-21','قرار مجلس الوزراء رقم 248 وتاريخ 12/6/1437هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/9a1c4977-c539-4e01-8c88-a9a700f2efa9/1','تم تعديل هذه المادة بموجب قرار مجلس الوزراء رقم (248) وتاريخ 12/ 6/ 1437هـ ، لتكون بالنص الآتي:

" تهدف الهيئة إلى تنظيم نشاط النقل العام والإشراف عليه وعلى سلامة تشغيل مرافقه وتجهيزاته وحسن إدارتها، وتوفيره بالمستوى الجيد والكلفة الملائمة، وتنظيم الاستثمار فيه بما يتفق مع أهداف التنمية الاقتصادية والاجتماعية في المملكة، وتراعى في كل ذلك الجوانب الفنية والبيئية والتكامل مع أنظمة النقل الجوي. وللهيئة في سبيل تحقيق أهدافها ممارسة المهمات والاختصاصات الآتية:

1 - إعداد الخطط السنوية والخمسية لنشاطا'),
('boe26-8927652b3839ce761cf99d89','cmpz61v1p03d3cwg2ujupskrj','يصرف للفرد أثناء مدة توقيفه أو سجنه لغرض التحقيق أو المحاكمة نصف صافي راتبه، فان لم تثبت ادانته او عوقب بغير الطرد، يعاد اليه ما استقطع من راتبه','2001-12-07','مرسوم ملكي رقم م/44 وتاريخ 1422/9/22هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/9b461caf-dc11-46bd-a8fd-ac74009a8724/1','- عُّدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/44) وتاريخ 1422/9/22هـ، لتصبح بالنص الآتي: "يصرف للفرد أثناء مدة توقيفه أو سجنه لغرض التحقيق أو المحاكمة نصف صافي راتبه، فان لم تثبت ادانته او عوقب بغير الطرد، يعاد اليه ما استقطع من راتبه".'),
('boe26-21f59019193cef64858795be','cmpz61vq303dbcwg2frymz1hn','يستحق الافراد علاوات فنية بموجب جدول العلاوات الفنية المرفق بهذا النظام، ويجوز الجمع بين علاوتين فنيتين فقط إذا قام بعملهما معا وتحدد اللائحة التنفيذية شروط منح هذه العلاوات وتصنيفها وفق التخصصات','1977-09-03','مرسوم ملكي رقم م/56 وتاريخ 1397/9/20هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/9b461caf-dc11-46bd-a8fd-ac74009a8724/1','- عُّدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/56) وتاريخ 1397/9/20هـ، لتصبح بالنص الآتي: "يستحق الافراد علاوات فنية بموجب جدول العلاوات الفنية المرفق بهذا النظام، ويجوز الجمع بين علاوتين فنيتين فقط إذا قام بعملهما معا وتحدد اللائحة التنفيذية شروط منح هذه العلاوات وتصنيفها وفق التخصصات".'),
('boe26-deaaeca1de60cb956cd9c659','cmpz61z1i03dzcwg2t74l9bre','يصرف للفرد بدل ترحيل وفقاً للأحكام التي تحددها اللائحة التنفيذية، وذلك عند تعيينه لأول مرة في الخدمة، أو نقله من بلد إلى آخر داخل المملكة، أو نقله من داخل المملكة إلى خارجها أو العكس، أو نقله من جهة إلى أخرى خارج المملكة، أو عند ابتعاثه أو إلحاقه لمدة تزيد على ستة أشهر، أو عند انتدابه لمدة أو مدد متواصلة تزيد على ثلاثة أشهر','2007-04-24','مرسوم ملكي رقم م/34 وتاريخ 1428/4/7هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/9b461caf-dc11-46bd-a8fd-ac74009a8724/1','- عُّدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/ 34) وتاريخ 1428/4/7هـ، لتكون بالنص الآتي: "يصرف للفرد بدل ترحيل وفقاً للأحكام التي تحددها اللائحة التنفيذية، وذلك عند تعيينه لأول مرة في الخدمة، أو نقله من بلد إلى آخر داخل المملكة، أو نقله من داخل المملكة إلى خارجها أو العكس، أو نقله من جهة إلى أخرى خارج المملكة، أو عند ابتعاثه أو إلحاقه لمدة تزيد على ستة أشهر، أو عند انتدابه لمدة أو مدد متواصلة تزيد على ثلاثة أشهر".'),
('boe26-a70fac42cd62fc5967cd51ed','cmpz61z1i03dzcwg2t74l9bre','يصرف للفرد بدل ترحيل وفقاً للأحكام التي تحددها اللائحة التنفيذية، وذلك عند تعيينه لأول مرة في الخدمة، أو نقله من بلد إلى آخر داخل المملكة، أو نقله من داخل المملكة إلى خارجها أو العكس، أو نقله من جهة إلى جهة أخرى خارج المملكة، أو عند ابتعاثه، أو إلحاقه لمدة تزيد على ستة أشهر، أو عند انتدابه لمدة أو لمدد ثلاثة أشهر فأكثر','2023-08-27','مرسوم ملكي رقم م/28 وتاريخ 1445/2/11هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/9b461caf-dc11-46bd-a8fd-ac74009a8724/1','- عُدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/28) وتاريخ 1445/2/11هـ، لتكون بالنص الآتي: "يصرف للفرد بدل ترحيل وفقاً للأحكام التي تحددها اللائحة التنفيذية، وذلك عند تعيينه لأول مرة في الخدمة، أو نقله من بلد إلى آخر داخل المملكة، أو نقله من داخل المملكة إلى خارجها أو العكس، أو نقله من جهة إلى جهة أخرى خارج المملكة، أو عند ابتعاثه، أو إلحاقه لمدة تزيد على ستة أشهر، أو عند انتدابه لمدة أو لمدد ثلاثة أشهر فأكثر".'),
('boe26-e16c5fa9ff86812e02ceb06e','cmpzcvci50bvjvtrkif3yztuk','يكون للمحافظ نائبان متفرغان يعاونانه في أداء مهماته ومسؤولياته. ويحدد المجلس بقرار منه اختصاصات كل منهما وصلاحياته ومهماته بناء على توصية من المحافظ. ولا يشارك أي من النائبين في مداولات القرار ولا في التصويت عليه.

يعين نائبا المحافظ بالمرتبة الممتازة بناءً على اقتراح من المحافظ،وتحديد مزاياهما بأمر ملكي.

يكلف المحافظ أحد النائبين ليحل محله عند غيابه.','2022-03-01','قرار مجلس الوزراء رقم 412 وتاريخ 1443/7/28هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/a292ec7e-85fb-4ceb-9ad0-ac9200ced829/1','- عُدلت هذه المادة وذلك بموجب قرار مجلس الوزراء رقم (412) وتاريخ 1443/7/28هـ، لتكون بالنص الآتي: 

يكون للمحافظ نائبان متفرغان يعاونانه في أداء مهماته ومسؤولياته. ويحدد المجلس بقرار منه اختصاصات كل منهما وصلاحياته ومهماته بناء على توصية من المحافظ. ولا يشارك أي من النائبين في مداولات القرار ولا في التصويت عليه.

يعين نائبا المحافظ بالمرتبة الممتازة بناءً على اقتراح من المحافظ،وتحديد مزاياهما بأمر ملكي.

يكلف المحافظ أحد النائبين ليحل محله عند غيابه.'),
('boe26-6019f0fe7c8e17bbc6eeaf7e','cmpzcv2ti095tvtrk4a3y1c7m','يعاقب بالسجن لمدة لا تقل عن (ستة) أشهر ولا تزيد على (سبع) سنوات، وبغرامة لا تقل عن (خمسين ألف) ريال ولا تزيد على (خمسمائة ألف)، أو بإحدى هاتين العقوبتين، كل من استولى بصورة غير مشروعة على أثر من ممتلكات الدولة','2021-03-25','مرسوم ملكي رقم م/67 وتاريخ 1442/8/12هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/a7d4493b-7c03-4c2d-b3c6-a9a700f275cd/1','- عُدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/67) وتاريخ 1442/8/12هـ، لتصبح بالنص الآتي: "يعاقب بالسجن لمدة لا تقل عن (ستة) أشهر ولا تزيد على (سبع) سنوات، وبغرامة لا تقل عن (خمسين ألف) ريال ولا تزيد على (خمسمائة ألف)، أو بإحدى هاتين العقوبتين، كل من استولى بصورة غير مشروعة على أثر من ممتلكات الدولة".'),
('boe26-bf48e4ceaec6e5e214445b29','cmpzcv2ti095uvtrknk6fq07a','يعاقب بالسجن لمدة لا تقل عن (ثلاثة) أشهر ولا تزيد على (ثلاث) سنوات، وبغرامة لا تقل عن (عشرين ألف) ريال ولا تزيد على (ثلاثمائة ألف) ريال، أو بإحدى هاتين العقوبتين، كل من:

1- تعدى على أثر، أو موقع أثري، أو موقع تراث عمراني، بإتلافه، أو تحويره، أو إزالته، أو نبشه، أو إلحاق الضرر به، أو تغيير معالمه، أو طمسه.

2- مسح أو نقب عن الآثار دون ترخيص','2021-03-25','مرسوم ملكي رقم م/67 وتاريخ 1442/8/12هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/a7d4493b-7c03-4c2d-b3c6-a9a700f275cd/1','/- عُدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/67) وتاريخ 1442/8/12هـ، لتصبح بالنص الآتي: "يعاقب بالسجن لمدة لا تقل عن (ثلاثة) أشهر ولا تزيد على (ثلاث) سنوات، وبغرامة لا تقل عن (عشرين ألف) ريال ولا تزيد على (ثلاثمائة ألف) ريال، أو بإحدى هاتين العقوبتين، كل من:

1- تعدى على أثر، أو موقع أثري، أو موقع تراث عمراني، بإتلافه، أو تحويره، أو إزالته، أو نبشه، أو إلحاق الضرر به، أو تغيير معالمه، أو طمسه.

2- مسح أو نقب عن الآثار دون ترخيص".'),
('boe26-bbab002d7b5bc9a390af1073','cmpzcv2ti095vvtrkwbno8fkc','يعاقب بالسجن لمدة لا تزيد على (سنتين) وبغرامة لا تزيد على (مائتي ألف) ريال، أو بإحدى هاتين العقوبتين، كل من:

1- قلد أثراً أو زيفه مدعياً أثريته.

2- قام بأي من أعمال الهدم الكلي أو الجزئي داخل حدود مواقع الآثار والتراث العمراني، أو بنى عليها، دون الحصول على موافقة من الوزارة.

3- خالف شروط الارتفاق وحقوقه المفروضة على الأراضي المجاورة لموقع الآثار.

4- انتشل -عمداً- أثراً غارقاً، أو نقله عن مكانه','2021-03-25','مرسوم ملكي رقم م/67 وتاريخ 1442/8/12هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/a7d4493b-7c03-4c2d-b3c6-a9a700f275cd/1','- عُدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/67) وتاريخ 1442/8/12هـ، لتصبح بالنص الآتي: "يعاقب بالسجن لمدة لا تزيد على (سنتين) وبغرامة لا تزيد على (مائتي ألف) ريال، أو بإحدى هاتين العقوبتين، كل من:

1- قلد أثراً أو زيفه مدعياً أثريته.

2- قام بأي من أعمال الهدم الكلي أو الجزئي داخل حدود مواقع الآثار والتراث العمراني، أو بنى عليها، دون الحصول على موافقة من الوزارة.

3- خالف شروط الارتفاق وحقوقه المفروضة على الأراضي المجاورة لموقع الآثار.

4- انتشل -عمداً- أثراً غارقاً، أو نقله عن مكانه".'),
('boe26-4fca03b01e3cadfed9e400bf','cmpzcv2ti095wvtrkq4zwampk','يعاقب بالسجن لمدة لا تزيد على (سنة) وبغرامة لا تزيد على (مائة ألف) ريال، أو بإحدى هاتين العقوبتين، كل من:

1- غيّر مبنى أو موقع تراث عمراني، أو أجرى في البيئة المحيطة به تعديلاً يؤدي إلى الإضرار به دون أخذ موافقة الوزارة.

2- نقل أنقاضاً أو أحجاراً أو أتربة من مواقع الآثار والتراث العمراني دون موافقة الوزارة.

3- رمى أنقاضاً أو مخلفات في مواقع الآثار والتراث العمراني.

4- شوّه أثراً أو تراثاً عمرانياً بالكتابة، أو الطلاء، أو النقش، أو إلصاق الإعلانات عليه، أو بافتعال الحريق','2021-03-25','مرسوم ملكي رقم م/67 وتاريخ 1442/8/12هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/a7d4493b-7c03-4c2d-b3c6-a9a700f275cd/1','- عُدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/67) وتاريخ 1442/8/12هـ، لتصبح بالنص الآتي: "يعاقب بالسجن لمدة لا تزيد على (سنة) وبغرامة لا تزيد على (مائة ألف) ريال، أو بإحدى هاتين العقوبتين، كل من:

1- غيّر مبنى أو موقع تراث عمراني، أو أجرى في البيئة المحيطة به تعديلاً يؤدي إلى الإضرار به دون أخذ موافقة الوزارة.

2- نقل أنقاضاً أو أحجاراً أو أتربة من مواقع الآثار والتراث العمراني دون موافقة الوزارة.

3- رمى أنقاضاً أو مخلفات في مواقع الآثار والتراث العمراني.

4- شوّه أثراً أو تراثاً عمرانياً'),
('boe26-2299500c4d427808c542213e','cmpzcv2ti095xvtrkr96llu5f','يعاقب بغرامة لا تزيد على (سبعين ألف) ريال كل من خالف الشروط المتعلقة بالآثار والتراث العمراني في الرخصة الممنوحة له الخاصة بترميم المباني الأثرية والتراثية وأحكامها','2021-03-25','مرسوم ملكي رقم م/67 وتاريخ 1442/8/12هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/a7d4493b-7c03-4c2d-b3c6-a9a700f275cd/1','- عُدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/67) وتاريخ 1442/8/12هـ، لتصبح بالنص الآتي: "يعاقب بغرامة لا تزيد على (سبعين ألف) ريال كل من خالف الشروط المتعلقة بالآثار والتراث العمراني في الرخصة الممنوحة له الخاصة بترميم المباني الأثرية والتراثية وأحكامها".'),
('boe26-5d429bb842c3695c4fedfb1e','cmpzcv2ti095yvtrkyshk48he','يعاقب بغرامة لا تزيد على (ستين ألف) ريال كل من:

1- حاز أو صنع نماذجاً أو نسخاً للآثار لأغراض تجارية دون ترخيص من الوزارة.

2- أخفى الآثار التي اكتشفها أو عثر عليها، أو امتنع عن تسليمها إلى الوزارة.

3- صدّر أثراً منقولاً أو باعه أو تصرف فيه، بالمخالفة لأحكام هذا النظام ولوائحه.

4- وضع لافتات أو لوحات أو غيرها من علامات الدعاية على مواقع الآثار والتراث العمراني دون موافقة الوزارة','2021-03-25','مرسوم ملكي رقم م/67 وتاريخ 1442/8/12هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/a7d4493b-7c03-4c2d-b3c6-a9a700f275cd/1','- عُدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/67) وتاريخ 1442/8/12هـ ، لتصبح بالنص الآتي: "يعاقب بغرامة لا تزيد على (ستين ألف) ريال كل من:

1- حاز أو صنع نماذجاً أو نسخاً للآثار لأغراض تجارية دون ترخيص من الوزارة.

2- أخفى الآثار التي اكتشفها أو عثر عليها، أو امتنع عن تسليمها إلى الوزارة.

3- صدّر أثراً منقولاً أو باعه أو تصرف فيه، بالمخالفة لأحكام هذا النظام ولوائحه.

4- وضع لافتات أو لوحات أو غيرها من علامات الدعاية على مواقع الآثار والتراث العمراني دون موافقة الوزارة".'),
('boe26-e1e5e147be02acc80f4c2f17','cmpzcv2ti095zvtrkxi2ww4ui','يعاقب بغرامة لا تزيد على (خمسين ألف) ريال كل من:

1- لم يقدم للوزارة بياناً بالآثار التي يملكها.

2- حاز قطعة أثرية أصلية غير مسجلة.

3- حاز أثراً لا يحمل ما يثبت شرعية ملكيته.

4- باع أو أجّر أو نقل ملكية أثر ثابت، أو موقع تراث عمراني مصنف، دون أخذ موافقة الوزارة.

5- زاول نشاط ترميم الآثار المنقولة لأغراض تجارية دون الحصول على ترخيص من الوزارة، أو خالف شروط الترخيص الممنوح له.

6- قام بعمل من أعمال الصيانة أو التجزئة والتقسيم في مباني وأحياء وقرى التراث العمراني المصنفة، دون الحصول على موافقة الوزارة.

7- قام من المتاحف بترميم قطعة أثرية يملكها ومسجلة في سجل الآثار دون الحصول على موافقة الوزارة.

8- زاول نشاط تشغيل المتاحف دون الحصول على ترخيص من الوزارة، أو خالف شروط الترخيص الممنوح له.

9- عرقل عمل فرق الوزارة في مواقع الآثار والتراث العمراني','2021-03-25','مرسوم ملكي رقم م/67 وتاريخ 1442/8/12هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/a7d4493b-7c03-4c2d-b3c6-a9a700f275cd/1','- عُدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/67) وتاريخ 1442/8/12هـ، لتصبح بالنص الآتي: "يعاقب بغرامة لا تزيد على (خمسين ألف) ريال كل من:

1- لم يقدم للوزارة بياناً بالآثار التي يملكها.

2- حاز قطعة أثرية أصلية غير مسجلة.

3- حاز أثراً لا يحمل ما يثبت شرعية ملكيته.

4- باع أو أجّر أو نقل ملكية أثر ثابت، أو موقع تراث عمراني مصنف، دون أخذ موافقة الوزارة.

5- زاول نشاط ترميم الآثار المنقولة لأغراض تجارية دون الحصول على ترخيص من الوزارة، أو خالف شروط الترخيص الممنوح له.

6- قام بعمل من أعمال '),
('boe26-bc85bf873c33d9e6b7b3d7c5','cmpz6ohut0b4pcwg2qc60qcjn','يكون للهيئة رئيس تنفيذي يعين ويعفى بقرار من المجلس بناء على ترشيح من الرئيس، ويحدد القرار أجره ومزاياه المالية الأخرى','2022-03-08','قرار مجلس الوزراء رقم 426 وتاريخ 1443/8/5هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/a98158eb-927b-4f8c-a9ff-a9a700f21e78/1','- عُدلت هذه المادة وذلك بموجب قرار مجلس الوزراء رقم (426) وتاريخ 1443/8/5هـ، لتكون بالنص الآتي: "يكون للهيئة رئيس تنفيذي يعين ويعفى بقرار من المجلس بناء على ترشيح من الرئيس، ويحدد القرار أجره ومزاياه المالية الأخرى".'),
('boe26-08d207234272f2e4c30dd8c8','cmpzcuwl007d7vtrk8ju2wtv9','يكون تأديب أعضاء الهيئة من اختصاص دائرة (مجلس التأديب) تشكل في مجلس الهيئة من ثلاثة أعضاء يصدر بتسميتهم قرار من رئيس الهيئة، وتصدر قراراتها بالأغلبية، ولا تكون نهائية إلا بعد موافقة مجلس الهيئة عليها','2015-02-02','مرسوم ملكي رقم م/31 وتاريخ 13/4/1436هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/ac892eff-4aa4-4b26-b312-a9a700f2663d/1','تم تعديل هذه المادة بموجب المرسوم الملكي رقم ( م/31) وتاريخ 13 / 4 / 1436 هـ ، لتكون بالصيغة الآتية :

"المادة الخامسة عشرة :

يكون تأديب أعضاء الهيئة من اختصاص دائرة (مجلس التأديب) تشكل في مجلس الهيئة من ثلاثة أعضاء يصدر بتسميتهم قرار من رئيس الهيئة، وتصدر قراراتها بالأغلبية، ولا تكون نهائية إلا بعد موافقة مجلس الهيئة عليها".'),
('boe26-013c722d880072dda3933b60','cmpzcuwl007cuvtrk3vd942nz','تشكل الهيئة من رئيس، ونائب رئيس – أو أكثر – ومن عدد كافٍ من الأعضاء','2015-02-02','مرسوم ملكي رقم م/31 وتاريخ 13/4/1436هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/ac892eff-4aa4-4b26-b312-a9a700f2663d/1','تم تعديل هذه المادة بموجب المرسوم الملكي رقم ( م/31) بتاريخ 13 / 4 / 1436 هـ ، لتكون بالصيغة الآتية :

" المادة الثانية:
تشكل الهيئة من رئيس، ونائب رئيس – أو أكثر – ومن عدد كافٍ من الأعضاء".'),
('boe26-53dce022a2d7c36a677b7f77','cmpzcuwl007cuvtrk3vd942nz','تشكل النيابة العامة من: النائب العام، ووكيل النيابة العامة، وعدد كافٍ من الأعضاء','2020-05-07','مرسوم ملكي رقم م/125 وتاريخ 1441/9/14هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/ac892eff-4aa4-4b26-b312-a9a700f2663d/1','-عُدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/125) وتاريخ 1441/9/14هـ، لتصبح بالنص الآتي: "تشكل النيابة العامة من: النائب العام، ووكيل النيابة العامة، وعدد كافٍ من الأعضاء".'),
('boe26-df5c6383dd2ce2abfe7c0670','cmpzcuwl007cxvtrka4e959kv','يكون لعمل أعضاء الهيئة الصفة القضائية، ويتمتعون بالاستقلال التام، ولا يخضعون في عملهم إلا لأحكام الشريعة الإسلامية، والأنظمة المرعية، وليس لأحد التدخل في مجال عملهم.','2015-02-02','مرسوم ملكي رقم م/31 وتاريخ 13/4/1436هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/ac892eff-4aa4-4b26-b312-a9a700f2663d/1','تم تعديل هذه المادة بموجب المرسوم الملكي رقم ( م/31) وتاريخ 13 / 4 / 1436 هـ ، لتكون بالصيغة الآتية :

"المادة الخامسة:

يكون لعمل أعضاء الهيئة الصفة القضائية، ويتمتعون بالاستقلال التام، ولا يخضعون في عملهم إلا لأحكام الشريعة الإسلامية، والأنظمة المرعية، وليس لأحد التدخل في مجال عملهم."'),
('boe26-fe54aea3559910ec362f9e26','cmpzcuwl007d1vtrkub0hs4fy','1 - تكون أسماء وظائف أعضاء الهيئة كما يأتي :

- ملازم تحقيق.

- محقق (ج).

- محقق (ب).

- محقق (أ).

- وكيل رئيس دائرة تحقيق وادعاء (ب).

- وكيل رئيس دائرة تحقيق وادعاء (أ).

- رئيس دائرة تحقيق وادعاء (ب).

- رئيس دائرة تحقيق وادعاء (أ).

- مدعي استئناف.

- رئيس دوائر تحقيق وادعاء.

2 - يعامل أعضاء الهيئة من حيث الرواتب والبدلات والمكافآت والمزايا معاملة نظرائهم في نظام القضاء، وذلك وفق جدول معادلة وظائف الهيئة بوظائف القضاة المعتمد نظاماً."

ثانيًا: يكون جدول معادلة وظائف الهيئة بوظائف القضاة – المشار إليه في المادة (التاسعة) من النظام – على النحو الآتي:

وظائف القضاء               وظائف أعضاء الهيئة

ملازم قضائي             ملازم تحقيق

قاضي ج                 محقق ج

قاضي ب                       محقق ب

قاضي أ                          محقق أ

وكيل محكمة ب      وكيل رئيس دائرة تحقيق وادعاء ب

وكيل محكمة أ     وكيل رئيس دائرة تحقيق وادعاء أ

رئيس محكمة ب    رئيس تحقيق وادعاء ب

رئيس محكمة أ    رئيس تحقيق وادعاء أ

قاضي استئناف    مدعي استئناف

رئيس محكمة استئناف  رئيس دوائر تحقيق وادعاء

رئيس المحكمة العليا      ـــــــــــــــــــــــــــــــــــــــــــــــــــــ','2015-02-02','مرسوم ملكي رقم م/31 وتاريخ 13/4/1436هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/ac892eff-4aa4-4b26-b312-a9a700f2663d/1','تم تعديل هذه المادة بموجب المرسوم الملكي رقم ( م/31) وتاريخ 13 / 4 / 1436 هـ ، لتكون بالصيغة الآتية :

"المادة التاسعة:

1 - تكون أسماء وظائف أعضاء الهيئة كما يأتي :

- ملازم تحقيق.

- محقق (ج).

- محقق (ب).

- محقق (أ).

- وكيل رئيس دائرة تحقيق وادعاء (ب).

- وكيل رئيس دائرة تحقيق وادعاء (أ).

- رئيس دائرة تحقيق وادعاء (ب).

- رئيس دائرة تحقيق وادعاء (أ).

- مدعي استئناف.

- رئيس دوائر تحقيق وادعاء.

2 - يعامل أعضاء الهيئة من حيث الرواتب والبدلات والمكافآت والمزايا معاملة نظرائهم في نظام القضاء'),
('boe26-579c83d90fb955705b881367','cmpzcuwl007d2vtrk2xkfj540','يعين رئيس الهيئة بمرتبة وزير بأمر ملكي بناءً على ترشيح المشرف من تتوافر فيه الشروط المطلوبة لشغل وظيفة رئيس دوائر تحقيق وادعاء على الأقل.

ويكون شغل وظائف أعضاء الهيئة الأخرى ونقلهم إلى جهات أخرى بأمر ملكي، بناءً على قرار من مجلس الهيئة، وتوصية المشرف.','2015-02-02','مرسوم ملكي رقم م/31 وتاريخ 13/4/1436هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/ac892eff-4aa4-4b26-b312-a9a700f2663d/1','تم تعديل هذه المادة بموجب المرسوم الملكي رقم ( م/31) وتاريخ 13 / 4 / 1436 هـ ، لتكون بالصيغة الآتية :

"المادة العاشرة:

يعين رئيس الهيئة بمرتبة وزير بأمر ملكي بناءً على ترشيح المشرف من تتوافر فيه الشروط المطلوبة لشغل وظيفة رئيس دوائر تحقيق وادعاء على الأقل.

ويكون شغل وظائف أعضاء الهيئة الأخرى ونقلهم إلى جهات أخرى بأمر ملكي، بناءً على قرار من مجلس الهيئة، وتوصية المشرف."'),
('boe26-7af50aec8de53d16a52a9de4','cmpzcuwl007d2vtrk2xkfj540','يعين النائب العام بمرتبة وزير بأمر ملكي، ممن تتوافر فيه الشروط المطلوبة لشغل وظيفة رئيس دوائر تحقيق وادعاء على الأقل.

وكون شغل وظائف أعضاء النيابة الأخرى ونقلهم إلى جهات أخرى بأمر ملكي، بناءً على قرار من مجلس النيابة العامة','2020-05-07','مرسوم ملكي رقم م/125 وتاريخ 1441/9/14هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/ac892eff-4aa4-4b26-b312-a9a700f2663d/1','- عُدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/125) وتاريخ 1441/9/14هـ، لتصبح بالنص الآتي: "يعين النائب العام بمرتبة وزير بأمر ملكي، ممن تتوافر فيه الشروط المطلوبة لشغل وظيفة رئيس دوائر تحقيق وادعاء على الأقل.

وكون شغل وظائف أعضاء النيابة الأخرى ونقلهم إلى جهات أخرى بأمر ملكي، بناءً على قرار من مجلس النيابة العامة".'),
('boe26-e989eeceb2ee6817d0aa778c','cmpzcuwl007d5vtrk7whhruwy','في غير حالات الوفاة، وبلوغ السن النظامية، وعدم ثبوت صلاحية العضو خلال فترة التجربة؛ تنتهي خدمة عضو النيابة بأمر ملكي بناء على قرار من مجلس النيابة','2020-05-07','مرسوم ملكي رقم م/125 وتاريخ 1441/9/14هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/ac892eff-4aa4-4b26-b312-a9a700f2663d/1','-عُدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/125) وتاريخ 1441/9/14هـ، لتصبح بالنص الآتي: "في غير حالات الوفاة، وبلوغ السن النظامية، وعدم ثبوت صلاحية العضو خلال فترة التجربة؛ تنتهي خدمة عضو النيابة بأمر ملكي بناء على قرار من مجلس النيابة".'),
('boe26-a48673973cb04ab43856857a','cmpzcuwl007d9vtrk22o34lqv','يرفع رئيس دائرة التفتيش – أو من ينبيه – الدعوى التأديبية بناء على طلب من النائب العام، ولا تقام هذه الدعوى إلا بناء على تحقيق يتولاه أحد أعضاء النيابة العامة الذي يندبه مجلس النيابة العامة. ويشترط في عضو النيابة العامة الذي يندب للتحقيق أن يكون في مرتبة أعلى من مرتبة العضو المحقق معه أو سابقاً له في الأقدمية إن كانا في مرتبة واحدة','2020-05-07','مرسوم ملكي رقم م/125 وتاريخ 1441/9/14هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/ac892eff-4aa4-4b26-b312-a9a700f2663d/1','- عُدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/125) وتاريخ 1441/9/14هـ، لتصبح بالنص الآتي: "يرفع رئيس دائرة التفتيش – أو من ينبيه – الدعوى التأديبية بناء على طلب من النائب العام، ولا تقام هذه الدعوى إلا بناء على تحقيق يتولاه أحد أعضاء النيابة العامة الذي يندبه مجلس النيابة العامة. ويشترط في عضو النيابة العامة الذي يندب للتحقيق أن يكون في مرتبة أعلى من مرتبة العضو المحقق معه أو سابقاً له في الأقدمية إن كانا في مرتبة واحدة".'),
('boe26-909f40d3bcb8b015d5d5778f','cmpzcuwl007dgvtrkm1ljj6i7','يجب أن يشتمل الحكم في الدعوى التأديبية على الأسباب التي بُني عليها، وأن تتلى أسبابه عند النطق به في جلسة سرية.','2015-02-02','مرسوم ملكي رقم م/31 وتاريخ 13/4/1436هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/ac892eff-4aa4-4b26-b312-a9a700f2663d/1','تم تعديل هذه المادة بموجب المرسوم الملكي رقم ( م/31) وتاريخ 13 / 4 / 1436 هـ ، لتكون بالصيغة الآتية :

"المادة الرابعة والعشرون:

يجب أن يشتمل الحكم في الدعوى التأديبية على الأسباب التي بُني عليها، وأن تتلى أسبابه عند النطق به في جلسة سرية."'),
('boe26-54067824466ead1a13135bb1','cmpzcuwl007dhvtrk1hmczbpp','العقوبات التأديبية التي يجوز توقيعها على عضو الهيئة هي :  اللوم، وإنهاء الخدمة.','2015-02-02','مرسوم ملكي رقم م/31 وتاريخ 13/4/1436هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/ac892eff-4aa4-4b26-b312-a9a700f2663d/1','تم تعديل هذه المادة بموجب المرسوم الملكي رقم ( م/31) وتاريخ 13 / 4 / 1436 هـ ، لتكون بالصيغة الآتية :

"المادة الخامسة والعشرون:

العقوبات التأديبية التي يجوز توقيعها على عضو الهيئة هي :  اللوم، وإنهاء الخدمة."'),
('boe26-bf5a1806e61bc8730efa749b','cmpzcuwl007divtrk7c0ughkx','تبلغ قرارات مجلس التأديب إلى المشرف، ويصدر أمر ملكي بتنفيذ عقوبة إنهاء الخدمة، وقرار من المشرف بتنفيذ عقوبة اللوم بناءً على توصية رئيس الهيئة.','2015-02-02','مرسوم ملكي رقم م/31 وتاريخ 13/4/1436هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/ac892eff-4aa4-4b26-b312-a9a700f2663d/1','تم تعديل هذه المادة بموجب المرسوم الملكي رقم ( م/31) وتاريخ 13 / 4 / 1436 هـ ، لتكون بالصيغة الآتية :

"المادة السادسة والعشرون:

تبلغ قرارات مجلس التأديب إلى المشرف، ويصدر أمر ملكي بتنفيذ عقوبة إنهاء الخدمة، وقرار من المشرف بتنفيذ عقوبة اللوم بناءً على توصية رئيس الهيئة."'),
('boe26-88a9f0ce29a844ac498f5610','cmpzcuwl007divtrk7c0ughkx','ترفع قرارات مجلس التأديب إلى مجلس النيابة العامة؛ للنظر فيها ، ويصدر أمر ملكي بتنفيذ عقوبة إنهاء الخدمة، وقرار من النائب العام بتنفيذ عقوبة اللوم','2020-05-07','مرسوم ملكي رقم م/125 وتاريخ 1441/9/14هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/ac892eff-4aa4-4b26-b312-a9a700f2663d/1','- عُدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/125) وتاريخ 1441/9/14هـ، لتصبح بالنص الآتي: "ترفع قرارات مجلس التأديب إلى مجلس النيابة العامة؛ للنظر فيها ، ويصدر أمر ملكي بتنفيذ عقوبة إنهاء الخدمة، وقرار من النائب العام بتنفيذ عقوبة اللوم".'),
('boe26-7761a9205594f8896913e9ad','cmpzcuwl007djvtrks8y57v6e','دون إخلال بالأحكام المنصوص عليها في هذا النظام، يتولى النائب العام الإشراف الإداري والمالي على النيابة العامة، وله صلاحيات الوزير بالنسبة إلى موظفي النيابة ومستخدميها، وهو المرجع فيما يصدر من النيابة في هذا الشأن إلى جميع الوزارات والجهات الأخرى','2020-05-07','مرسوم ملكي رقم م/125 وتاريخ 1441/9/14هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/ac892eff-4aa4-4b26-b312-a9a700f2663d/1','- عُدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/125) وتاريخ 1441/9/14هـ، لتصبح بالنص الآتي: "دون إخلال بالأحكام المنصوص عليها في هذا النظام، يتولى النائب العام الإشراف الإداري والمالي على النيابة العامة، وله صلاحيات الوزير بالنسبة إلى موظفي النيابة ومستخدميها، وهو المرجع فيما يصدر من النيابة في هذا الشأن إلى جميع الوزارات والجهات الأخرى".'),
('boe26-f03c00bc71b1503009f69ebf','cmpz63ftc03vhcwg2sek4u5mt','تحدد رسوم القيد في  سجل الوكالات    كالآتي:

خمسمائة ريال للتاجر الفرد والشركة.
وتدفع الرسوم لمرة واحدة.','1973-04-23','مرسوم ملكي رقم م/8 وتاريخ 20/3/1393هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/b19a8aa6-7b50-43f0-ab8c-a9a700f1a446/1','تم تعديل هذه المادة بموجب المرسوم الملكي رقم (م/8) وتاريخ 20 / 3 / 1393 هـ ، لتصبح بالنص الآتي:

" تحدد رسوم القيد في  سجل الوكالات    كالآتي:

خمسمائة ريال للتاجر الفرد والشركة.
وتدفع الرسوم لمرة واحدة."'),
('boe26-33c8b318ee2697e4b1576c4d','cmpz63fne03vfcwg2g2y4r4h4','كل من يخالف أحكام هذا النظام ولائحته التنفيذية يعاقب بغرامة لا تقل عن خمسة آلاف ريال ولا تتجاوز خمسين ألف ريال مع نشر العقوبة على نفقة المخالف وذلك دون إخلال بحق من لحقه ضرر من المخالفة في المطالبة بالتعويض.
فإن كانت المخالفة منسوبة لأجنبي أو لشركة سعودية فيها شريك أو أكثر غير سعودي أصبحت العقوبة بالإضافة إلى الغرامة تصفية الأعمال إداريا مع جواز الحرمان من ممارسة التجارة دائما أو لمدة معنية، ويجوز   لوزير الداخلية    الأمر   بترحيل الأجنبي    من البلاد في ضوء العقوبة المحكوم بها، وعلى   وزارة التجارة    إبلاغه عن الأجنبي أو الشريك الغير سعودي.','1980-06-23','مرسوم ملكي رقم م/32 وتاريخ 10/8/1400هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/b19a8aa6-7b50-43f0-ab8c-a9a700f1a446/1','عدلت هذه المادة بموجب المرسوم الملكي رقم (م/32) بتاريخ 10 / 8 / 1400 هـ ، لتكون كما يلى :

كل من يخالف أحكام هذا النظام ولائحته التنفيذية يعاقب بغرامة لا تقل عن خمسة آلاف ريال ولا تتجاوز خمسين ألف ريال مع نشر العقوبة على نفقة المخالف وذلك دون إخلال بحق من لحقه ضرر من المخالفة في المطالبة بالتعويض.
فإن كانت المخالفة منسوبة لأجنبي أو لشركة سعودية فيها شريك أو أكثر غير سعودي أصبحت العقوبة بالإضافة إلى الغرامة تصفية الأعمال إداريا مع جواز الحرمان من ممارسة التجارة دائما أو لمدة معنية، ويجوز   لوزير '),
('boe26-13366ef05b3fa51a606328f8','cmpz801va0cad7b6w4zoex1at','( تحديد الراتب الشهري للوزراء ومن في مرتبتهم بخمسة وأربعين ألف ريال ).','1981-07-29','مرسوم ملكي رقم م/40 وتاريخ 28/9/1401هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/b2a002e4-a3da-474b-9735-a9a700f2386c/1','عدلت هذه المادة عدة تعديلات كان آخرها بالمرسوم الملكي رقم (م/40) وتاريخ 28 / 9 / 1401 هـ ، لتصبح بالنص التالى :

( تحديد الراتب الشهري للوزراء ومن في مرتبتهم بخمسة وأربعين ألف ريال ).'),
('boe26-f1c0bf3288752002b2d5cf65','cmpz8020j0caf7b6wz94tzk99','( يُحدَّد الراتب الشهري لنواب الوزراء وموظفي المرتبة المُمتازة بثلاثين ألف ريال) .','1981-07-29','مرسوم ملكي رقم م/40 وتاريخ 28/9/1401هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/b2a002e4-a3da-474b-9735-a9a700f2386c/1','عدلت هذه المادة عدة تعديلات كان آخرها بالمرسوم الملكي رقم (م/40) وتاريخ 28 / 9 / 1401 هـ ، لتصبح بالنص التالى :

( يُحدَّد الراتب الشهري لنواب الوزراء وموظفي المرتبة المُمتازة بثلاثين ألف ريال) .'),
('boe26-b0c111ee8ea8bf0d48cc73eb','cmpz8025t0cah7b6wxkrc7fol','4-

أ- تُمنح إجازة سنوية للوزراء ومن هم في مرتبة وزير والمرتبة الممتازة، وتُحدد مدتها لكل فئة بأمر من رئيس مجلس الوزراء.

ب- يوافق رئيس مجلس الوزراء على طلب التمتع بالإجازة للوزراء، ولمن هم في مرتبة وزير أو المرتبة الممتازة، ويستثنى من ذلك ما يأتي:

ما يتصل بلطب التمتع بالإجازة لمن هم في مرتبة وزير أو المرتبة الممتازة من منسوبي أي وزارة والأجهزة المرتبطة بتلك الوزارة أو وزيرها، فيوافق الوزير عليه.

ما يتصل بطلب التمتع بالإجازة لمن هم في مرتبة وزير أو المرتبة الممتازة من منسوبي أي جهاز مستقل يرتبط مباشرة بالملك أو برئيس مجلس الوزراء والأجهزة المرتبطة بذلك الجهاز أو رئيسه، فيوافق رئيس الجهاز المستقل عليه','2021-02-25','مرسوم ملكي رقم م/56 وتاريخ 1442/7/13هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/b2a002e4-a3da-474b-9735-a9a700f2386c/1','- عُدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/56) وتاريخ 1442/7/13هـ. لتصبح بالنص الآتي:

"4-

أ- تُمنح إجازة سنوية للوزراء ومن هم في مرتبة وزير والمرتبة الممتازة، وتُحدد مدتها لكل فئة بأمر من رئيس مجلس الوزراء.

ب- يوافق رئيس مجلس الوزراء على طلب التمتع بالإجازة للوزراء، ولمن هم في مرتبة وزير أو المرتبة الممتازة، ويستثنى من ذلك ما يأتي:

ما يتصل بلطب التمتع بالإجازة لمن هم في مرتبة وزير أو المرتبة الممتازة من منسوبي أي وزارة والأجهزة المرتبطة بتلك الوزارة أو وزيرها، فيوافق الوزير عليه.

م'),
('boe26-b5741813c5cae93a67930bec','cmpz5yvtz02dzcwg2kamjt5yn','تعقد اللجنة اجتماعين عاديين كل عام، ويحق لرئيس اللجنة أو لنصف الأعضاء دعوة اللجنة إلى عقد اجتماعات غير عادية','2021-11-16','قرار مجلس الوزراء رقم 211 وتاريخ 1443/4/11هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/b2c545f0-d65f-4c13-b712-a9a700f193b6/1','- عُدلت هذه المادة وذلك بموجب قرار مجلس الوزراء رقم (211) وتاريخ 1443/4/11هـ، لتكون بالنص الآتي:

"تعقد اللجنة اجتماعين عاديين كل عام، ويحق لرئيس اللجنة أو لنصف الأعضاء دعوة اللجنة إلى عقد اجتماعات غير عادية".'),
('boe26-c933e3afb248030e0c969535','cmpz62drh03ivcwg224kqp4i1','يكون لصاحب البيانات الشخصية -وفقاً للأحكام الواردة في النظام وما تحدده اللوائح- الحقوق الآتية:

1- الحق في العلم، ويشمل ذلك إحاطته علماً بالمسوغ النظامي لجمع بياناته الشخصية والغرض من جمعها.

2- الحق في وصوله إلى بياناته الشخصية المتوافرة لدى جهة التحكم، وفق الضوابط والإجراءات التي تحددها اللوائح، ودون إخلال بما ورد في المادة (التاسعة) من النظام.

3- الحق في طلب الحصول على بياناته الشخصية المتوافرة لدى جهة التحكم بصيغة مقروءة وواضحة، وفق الضوابط والإجراءات التي تحددها اللوائح.

4- الحق في طلب تصحيح بياناته الشخصية المتوافرة لدى جهة التحكم، أو إتمامها، أو تحديثها.

5- الحق في طلب إتلاف بياناته الشخصية المتوافرة لدى جهة التحكم مما انتهت الحاجة إليه منها، وذلك دون إخلال بما تقضي به المادة (الثامنة عشرة) من النظام.','2023-03-27','مرسوم ملكي رقم م/148 وتاريخ 1444/9/5هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/b7cfae89-828e-4994-b167-adaa00e37188/1','- عُدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/148) وتاريخ 1444/9/5هـ، لتكون بالنص الآتي: "يكون لصاحب البيانات الشخصية -وفقاً للأحكام الواردة في النظام وما تحدده اللوائح- الحقوق الآتية:

1- الحق في العلم، ويشمل ذلك إحاطته علماً بالمسوغ النظامي لجمع بياناته الشخصية والغرض من جمعها.

2- الحق في وصوله إلى بياناته الشخصية المتوافرة لدى جهة التحكم، وفق الضوابط والإجراءات التي تحددها اللوائح، ودون إخلال بما ورد في المادة (التاسعة) من النظام.

3- الحق في طلب الحصول على بياناته الشخصية المتوافرة لد'),
('boe26-2aa960d142d623d1900b340d','cmpz62efa03j3cwg2n7g4zaf7','مع مراعاة ما ينص عليه النظام واللوائح في شأن الإفصاح عن البيانات الشخصية، على جهة التحكم عند اختيارها جهة المعالجة أن تلتزم باختيار الجهة التي توفر الضمانات اللازمة لتنفيذ أحكام النظام واللوائح، وعليها التحقق من التزام تلك الجهة بأحكام النظام واللوائح، ولا يخل ذلك بمسؤولياتها تجاه صاحب البيانات الشخصية أو الجهة المختصة بحسب الأحوال. وتحدد اللوائح الأحكام اللازمة لذلك، على أن تشتمل على الأحكام المتعلقة بأي تعاقدات لاحقة تقوم بها جهة المعالجة','2023-03-27','مرسوم ملكي رقم م/148 وتاريخ 1444/9/5هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/b7cfae89-828e-4994-b167-adaa00e37188/1','- عُدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/148) وتاريخ 1444/9/5هـ، لتكون بالنص الآتي: "مع مراعاة ما ينص عليه النظام واللوائح في شأن الإفصاح عن البيانات الشخصية، على جهة التحكم عند اختيارها جهة المعالجة أن تلتزم باختيار الجهة التي توفر الضمانات اللازمة لتنفيذ أحكام النظام واللوائح، وعليها التحقق من التزام تلك الجهة بأحكام النظام واللوائح، ولا يخل ذلك بمسؤولياتها تجاه صاحب البيانات الشخصية أو الجهة المختصة بحسب الأحوال. وتحدد اللوائح الأحكام اللازمة لذلك، على أن تشتمل على الأحكام المتعلقة'),
('boe26-0993af39b55ea67cdf7593d0','cmpz62er703j7cwg2lkj4svm6','لا يجوز لجهة التحكم جمع البيانات الشخصية إلا من صاحبها مباشرةً، ولا تجوز مُعالجة تلك البيانات إلا لتحقيق الغرض الذي جُمعت من أجله. ومع ذلك، يجوز لجهة التحكم جمع البيانات الشخصية من غير صاحبها مباشرةً، أو مُعالجتها لغرض آخر غير الذي جمعت من أجله، وذلك في الأحوال الآتية:

1- إذا وافق صاحب البيانات الشخصية على ذلك، وفقاً لأحكام النظام.

2- إذا كانت البيانات الشخصية متاحة للعموم، أو جرى جمعها من مصدر متاح للعموم.

3- إذا كانت جهة التحكم جهة عامة، وكان جمع البيانات الشخصية أومعالجتها؛ مطلوباً لأغراض المصلحة العامة أو لأغراض أمنية أو لتنفيذ نظام آخر أو لاستيفاء مُتطلبات قضائية.

4- إذا كان التقيد بهذا الحظر قد يُلحق ضرراً بصاحب البيانات الشخصية أو يؤثر على مصالحه الحيوية.

5- إذا كان جمع البيانات الشخصية أو معالجتها ضروريا ً لحماية الصحة العامة أو السلامة العامة أو حماية حياة فرد أو أفراد معينين أو حماية صحتهم.

6- إذا كانت البيانات الشخصية لن تُسجل أو تُحفظ في صيغة تجعل من الممكن تحديد هوية صاحبها ومعرفته بصورة مباشرة أو غير مباشرة.

7- إذا كان جمع البيانات الشخصية أو معالجتها ضرورياً لتحقيق مصالح مشروعة لجهة التحكم، ما لم يخل ذلك بحقوق صاحب البيانات الشخصية أو يتعارض مع مصالحه ولم تكن تلك البيانات بيانات حساسة.','2023-03-27','مرسوم ملكي رقم م/148 وتاريخ 1444/9/5هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/b7cfae89-828e-4994-b167-adaa00e37188/1','- عُدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/148) وتاريخ 1444/9/5هـ، لتكون بالنص الآتي: "لا يجوز لجهة التحكم جمع البيانات الشخصية إلا من صاحبها مباشرةً، ولا تجوز مُعالجة تلك البيانات إلا لتحقيق الغرض الذي جُمعت من أجله. ومع ذلك، يجوز لجهة التحكم جمع البيانات الشخصية من غير صاحبها مباشرةً، أو مُعالجتها لغرض آخر غير الذي جمعت من أجله، وذلك في الأحوال الآتية:

1- إذا وافق صاحب البيانات الشخصية على ذلك، وفقاً لأحكام النظام.

2- إذا كانت البيانات الشخصية متاحة للعموم، أو جرى جمعها من مصدر متاح'),
('boe26-b36d1cf664abfa4d91b165c2','cmpz62f3303jbcwg2gta5w5rk','على جهة التحكم أن تعتمد سياسة للخصوصية، وأن تجعلها متاحة لأصحاب البيانات الشخصية ليطلعوا عليها عند جمع بياناتهم. على أن تشتمل تلك السياسة على تحديد الغرض من جمعها، ومُحتوى البيانات الشخصية المطلوب جمعها، وطريقة جمعها، ووسيلة حفظها، وكيفية معالجتها، وكيفية إتلافها، وحقوق صاحبها فيما يتعلق بها، وكيفية ممارسة هذه الحقوق','2023-03-27','مرسوم ملكي رقم م/148 وتاريخ 1444/9/5هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/b7cfae89-828e-4994-b167-adaa00e37188/1','- عُدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/148) وتاريخ 1444/9/5هـ، لتكون بالنص الآتي:

" على جهة التحكم أن تعتمد سياسة للخصوصية، وأن تجعلها متاحة لأصحاب البيانات الشخصية ليطلعوا عليها عند جمع بياناتهم. على أن تشتمل تلك السياسة على تحديد الغرض من جمعها، ومُحتوى البيانات الشخصية المطلوب جمعها، وطريقة جمعها، ووسيلة حفظها، وكيفية معالجتها، وكيفية إتلافها، وحقوق صاحبها فيما يتعلق بها، وكيفية ممارسة هذه الحقوق".'),
('boe26-676811d7bcbf90e47adcbe33','cmpz62geo03jrcwg2srv8er1t','1- تشعر جهة التحكم الجهة المختصة عند علمها بحدوث تسرب لبيانات شخصية أو تلفها أو وصول غير مشروع إليها؛ وفقاً لما تحدده اللوائح.

2- تشعر جهة التحكم صاحب البيانات الشخصية إذا كان من شأن حدوث تسرب لبيانات شخصية أو تلفها أو وصول غير مشروع إليها أن يرتب ضرراً على بياناته أو يتعارض مع حقوقه أو مصالحه؛ وفقاً لما تحدده اللوائح','2023-03-27','مرسوم ملكي رقم م/148 وتاريخ 1444/9/5هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/b7cfae89-828e-4994-b167-adaa00e37188/1','- عُدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/148) وتاريخ 1444/9/5هـ، لتكون بالنص الآتي:

"1- تشعر جهة التحكم الجهة المختصة عند علمها بحدوث تسرب لبيانات شخصية أو تلفها أو وصول غير مشروع إليها؛ وفقاً لما تحدده اللوائح.

2- تشعر جهة التحكم صاحب البيانات الشخصية إذا كان من شأن حدوث تسرب لبيانات شخصية أو تلفها أو وصول غير مشروع إليها أن يرتب ضرراً على بياناته أو يتعارض مع حقوقه أو مصالحه؛ وفقاً لما تحدده اللوائح".'),
('boe26-3e9c17a42e65e821400bfccf','cmpz62k1v03kzcwg27wvvzuk7','يصدر رئيس الجهة المختصة اللوائح، وذلك في مدة لا تتجاوز (سبعمائة وعشرين) يوماً من تاريخ صدور النظام، على أن يُنسِّق -قبل إصدارها- مع: (وزارة الاتصالات وتقنية المعلومات، ووزارة الخارجية، وهيئة الاتصالات والفضاء والتقنية، وهيئة الحكومة الرقمية، والهيئة الوطنية للأمن السيبراني، والمجلس الصحي السعودي، والبنك المركزي السعودي)، كلٌّ فيما يخصه.','2023-03-27','مرسوم ملكي رقم م/148 وتاريخ 1444/9/5هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/b7cfae89-828e-4994-b167-adaa00e37188/1','- عُدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/148) وتاريخ 1444/9/5هـ، لتكون بالنص الآتي: 

"يصدر رئيس الجهة المختصة اللوائح، وذلك في مدة لا تتجاوز (سبعمائة وعشرين) يوماً من تاريخ صدور النظام، على أن يُنسِّق -قبل إصدارها- مع: (وزارة الاتصالات وتقنية المعلومات، ووزارة الخارجية، وهيئة الاتصالات والفضاء والتقنية، وهيئة الحكومة الرقمية، والهيئة الوطنية للأمن السيبراني، والمجلس الصحي السعودي، والبنك المركزي السعودي)، كلٌّ فيما يخصه."'),
('boe26-0f0fdba803b9d6f9d64aee80','cmpzcvb5i0be5vtrkanic9kv4','يجوز في حالة النقل من دائرة جمركية إلى أخرى إعفاء أصحاب العلاقة من تقديم بيان جمركي تفصيلي في مركز الدخول، وتتم الإحالة وفق المستندات والشروط التي يحددها المدير العام".','2024-01-21','مرسوم ملكي رقم م/124 وتاريخ 1445/7/9هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/b93d0275-775f-482a-9d52-a9a700f2ca15/1','- عُدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/124) وتاريخ 1445/7/9هـ، لتصبح على النحو الآتي:

المادة (72): "يجوز في حالة النقل من دائرة جمركية إلى أخرى إعفاء أصحاب العلاقة من تقديم بيان جمركي تفصيلي في مركز الدخول، وتتم الإحالة وفق المستندات والشروط التي يحددها المدير العام".'),
('boe26-03f9fddbf578db44bb84e4f9','cmpzcvb5i0bezvtrknf2899kk','يعفى من الضرائب (الرسوم) الجمركية ما يلي:

أ- مستوردات القوات المسلحة وقوى الأمن الداخلي بجميع قطاعاتها من ذخائر وأسلحة وتجهيزات ووسائط نقل عسكرية وقطعها وأي مادة أخرى بقرار من مجلس الوزراء أو من الجهة المخولة بذلك في كل دولة.

ب- مستوردات الجمارك ذات الطابع الأمني بقرار من مجلس الوزراء أو من الجهة المخولة بذلك في كل دولة".','2024-01-21','مرسوم ملكي رقم م/124 وتاريخ 1445/7/9هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/b93d0275-775f-482a-9d52-a9a700f2ca15/1','- عُدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/124) وتاريخ 1445/7/9هـ، لتصبح بالنص الآتي:

المادة (102): "يعفى من الضرائب (الرسوم) الجمركية ما يلي:

أ- مستوردات القوات المسلحة وقوى الأمن الداخلي بجميع قطاعاتها من ذخائر وأسلحة وتجهيزات ووسائط نقل عسكرية وقطعها وأي مادة أخرى بقرار من مجلس الوزراء أو من الجهة المخولة بذلك في كل دولة.

ب- مستوردات الجمارك ذات الطابع الأمني بقرار من مجلس الوزراء أو من الجهة المخولة بذلك في كل دولة".'),
